/* @autogenerated */
package net.civeira.phylax.feature.oauth.webauthn.infrastructure.driver;

import java.net.URI;
import java.util.Optional;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.infrastructure.CurrentRequest;
import net.civeira.phylax.feature.identity.tenant.domain.gateway.TenantFilter;
import net.civeira.phylax.feature.identity.tenant.domain.gateway.TenantQueryRepositoryGateway;
import net.civeira.phylax.feature.identity.tenantconfig.domain.gateway.TenantConfigFilter;
import net.civeira.phylax.feature.identity.tenantconfig.domain.gateway.TenantConfigQueryRepositoryGateway;

/**
 * Resolves the WebAuthn relying party of a tenant: its id, its display name and the origin the
 * browser must report.
 *
 * <p>
 * The origin comes from the public host of the server ({@code oidc.base-url}, else the forwarded
 * headers or the request), never from the {@code Origin} header the caller sends: a ceremony made
 * on another site must not verify here.
 * </p>
 */
@ApplicationScoped
@RequiredArgsConstructor
public class WebAuthnRelyingParty {

  private final TenantQueryRepositoryGateway tenants;
  private final TenantConfigQueryRepositoryGateway tenantConfigs;
  private final CurrentRequest currentRequest;

  /**
   * Public host for links and origins; without it, derived from the request.
   */
  @ConfigProperty(name = "oidc.base-url")
  private final Optional<String> baseUrl;

  /**
   * The relying party of one tenant.
   *
   * @param id rp id: the host, unless the tenant configures another one
   * @param name rp display name: the tenant name, unless the tenant configures another one
   * @param origin expected browser origin ({@code scheme://host[:port]})
   */
  public record Party(String id, String name, String origin) {}

  /**
   * Resolves the relying party for a tenant.
   *
   * @param tenantName tenant name of the endpoint
   * @return the relying party
   */
  public Party resolve(String tenantName) {
    String origin = origin();
    String host = URI.create(origin).getHost();
    String rpId = host != null ? host : tenantName;
    String rpName = tenantName;
    var tenant = tenants.find(TenantFilter.builder().name(tenantName).build()).orElse(null);
    if (tenant != null) {
      var cfg = tenantConfigs.find(TenantConfigFilter.builder().tenant(tenant).build());
      if (cfg.isPresent()) {
        rpId = cfg.get().getWebauthnRpId().filter(id -> !id.isBlank()).orElse(rpId);
        rpName = cfg.get().getWebauthnRpName().filter(name -> !name.isBlank()).orElse(rpName);
      }
    }
    return new Party(rpId, rpName, origin);
  }

  private String origin() {
    String base = baseUrl.filter(url -> !url.isBlank()).orElseGet(currentRequest::getPublicHost);
    URI uri = URI.create(base);
    if (uri.getScheme() == null || uri.getRawAuthority() == null) {
      return "http://localhost";
    }
    return uri.getScheme() + "://" + uri.getRawAuthority();
  }
}
